edits.replace:
// 广乐：原生播放时 src 已被换成 /media 中转地址，与 audioSrc（插件直链）必然不等。
// 改成“元素上已经有源”，起播交给原生 ExoPlayer，影子牌只负责给频谱供流。
if (isNativePlaybackActive() && hasShadowSource(audioRef.current)) {
    if (shouldAutoPlayRef.current && !isLyricsLoading) {
        shouldAutoPlayRef.current = false;
        syncOutputGain(getTargetPlaybackVolume(), 0);
        setupAudioAnalyzer();
        setPlayerState(PlayerState.PLAYING);
    }
    return;
}
if (audioRef.current.getAttribute('src') !== audioSrc) return;
